sn_aia_tool.script:
(function(inputs) {
    var incidentNumber = inputs.incident_number;

    var incGR = new GlideRecord('incident');
    incGR.addQuery('number', incidentNumber);
    incGR.query();

    if (!incGR.next()) {
        gs.print('ERROR: Incident not found for number: ' + incidentNumber);
        return;
    }
    if (!incGR.cmdb_ci) {
        return { error: 'No CI linked to this incident' };
    }

    // ── Step 1: resolve the CI using its actual class
    var ciBase = new GlideRecord('cmdb_ci');
    if (!ciBase.get(incGR.getValue('cmdb_ci'))) {
        return { error: 'CI record not found' };
    }
    var ciActualClass = ciBase.getValue('sys_class_name');
    var ciGR = new GlideRecord(ciActualClass);
    if (!ciGR.get(ciBase.getUniqueValue())) {
        ciGR = ciBase;
    }

    var modelSysId = ciGR.getValue('model_id');
    if (!modelSysId) {
        return { error: 'CI has no model assigned', ci_name: ciGR.getValue('name') };
    }

    // ── Step 2: resolve the model using its actual class
    var modelBase = new GlideRecord('cmdb_model');
    if (!modelBase.get(modelSysId)) {
        return { error: 'Model record not found' };
    }
    var modelActualClass = modelBase.getValue('sys_class_name');
    var modelGR = new GlideRecord(modelActualClass);
    if (!modelGR.get(modelBase.getUniqueValue())) {
        modelGR = modelBase;
    }

    // ── Step 3: query the lifecycle table for THIS model's "End of life" phase
    // NOTE: confirm exact field/value names on your instance using the
    // diagnostic script above before relying on this in production
    var eolDate = '';
    var eosDate = '';

    var lifecycleGR = new GlideRecord('cmdb_hardware_model_lifecycle');
    lifecycleGR.addQuery('model', modelGR.getUniqueValue()); // adjust field name if different
    lifecycleGR.query();

    while (lifecycleGR.next()) {
        var phase = lifecycleGR.getDisplayValue('lifecycle_phase'); // adjust field name if different
        var phaseStart = lifecycleGR.getValue('end_date');  // adjust field name if different

        if (phase === 'End of life') {
            eolDate = phaseStart;
        } else if (phase === 'End of support') {
            eosDate = phaseStart;
        }
    }

    // ── Step 4: calculate status off the End of Life date
    var eolStatus = 'unknown';
    if (eolDate) {
        var eolGdt = new GlideDateTime(eolDate);
        var now = new GlideDateTime();
        var threeMonthsOut = new GlideDateTime();
        threeMonthsOut.addMonthsLocalTime(3);

        if (eolGdt.before(now)) {
            eolStatus = 'reached';
        } else if (eolGdt.before(threeMonthsOut)) {
            eolStatus = 'approaching';
        } else {
            eolStatus = 'not_due';
        }
    }


     if (eolStatus === 'reached' || eolStatus === 'approaching') {

        var eolGdtDisplay = new GlideDateTime(eolDate);
        var formattedEolDate = eolGdtDisplay.getDisplayValue(); // respects user's date format/timezone

        var noteText = '';

        if (eolStatus === 'reached') {
            noteText = 'Asset requires attention due to its EOL. '
                + 'This model reached End of Life on ' + formattedEolDate + '.';
        } else if (eolStatus === 'approaching') {
            noteText = 'Asset requires attention due to its EOL. '
                + 'This model is approaching End of Life, scheduled for ' + formattedEolDate + '.';
        }

        incGR.work_notes = noteText;
        incGR.update();

        gs.print('========================================');
        gs.print('WORK NOTE ADDED');
        gs.print('========================================');
        gs.print(noteText);
    } else {
        gs.print('No EOL work note added — status is: ' + eolStatus);
    }

    return {
        ci_sys_id: ciGR.getUniqueValue(),
        ci_class: ciActualClass,
        ci_name: ciGR.getValue('name'),
        model_sys_id: modelGR.getUniqueValue(),
        model_class: modelActualClass,
        model_name: modelGR.getValue('name'),
        manufacturer: modelGR.getDisplayValue('manufacturer'),
        eol_date: eolDate,
        eos_date: eosDate,
        eol_status: eolStatus
    };

})(inputs);
